local BobbinWinderMaker = {}
local PRODUCTS = {
    iron_bobbin_winder = { name = "Železni navijalec vretencev", ironCost = 3, woodCost = 3, leatherCost = 1, time = 5, cost = 170, prestige = 4, happiness = 2, description = "Železni navijalec za navijanje vretencev." },
    bronze_bobbin_winder = { name = "Bronast navijalec vretencev", bronzeCost = 3, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 410, prestige = 6, happiness = 3, description = "Bronast navijalec za hitro navijanje." },
    silver_bobbin_winder = { name = "Srebrni navijalec vretencev", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 990, prestige = 11, happiness = 4, description = "Srebrni navijalec za plemiške tkače." },
    gilded_bobbin_winder = { name = "Pozlačeni navijalec vretencev", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2130, prestige = 20, happiness = 5, description = "Pozlačeni navijalec za dvorne tkače." },
    jewel_set_bobbin_winder = { name = "Draguljasti navijalec vretencev", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4600, prestige = 36, happiness = 7, description = "Draguljasti navijalec za kraljevske tkače." },
    royal_sovereign_bobbin_winder = { name = "Kraljevski suvereni navijalec vretencev", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 9800, prestige = 68, happiness = 13, description = "Suvereni navijalec z biseri za krono." },
}
local BUILDINGS = {
    bobbinwinder_workshop = { name = "Navijalna delavnica", cost = { gold = 345, wood = 185, stone = 135, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    bobbinwinder_house = { name = "Navijalna hiša", cost = { gold = 1230, wood = 370, stone = 275, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_bobbinwinder_atelier = { name = "Mojstrski navijalni atelje", cost = { gold = 3080, wood = 425, stone = 525, silver = 36, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_bobbinwinder_palace = { name = "Suverena navijalna palača", cost = { gold = 13150, wood = 655, stone = 835, gold = 84, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
BobbinWinderMaker.ironStock = 14; BobbinWinderMaker.bronzeStock = 12; BobbinWinderMaker.woodStock = 14; BobbinWinderMaker.leatherStock = 10; BobbinWinderMaker.silverStock = 8; BobbinWinderMaker.goldStock = 6; BobbinWinderMaker.jewelStock = 4; BobbinWinderMaker.pearlStock = 4
BobbinWinderMaker.productStock = {}; BobbinWinderMaker.buildings = {}; BobbinWinderMaker.maker = nil; BobbinWinderMaker.activeMaking = {}; BobbinWinderMaker.totalProducts = 0; BobbinWinderMaker.dayTimer = 0
function BobbinWinderMaker.init() BobbinWinderMaker.ironStock=14; BobbinWinderMaker.bronzeStock=12; BobbinWinderMaker.woodStock=14; BobbinWinderMaker.leatherStock=10; BobbinWinderMaker.silverStock=8; BobbinWinderMaker.goldStock=6; BobbinWinderMaker.jewelStock=4; BobbinWinderMaker.pearlStock=4; BobbinWinderMaker.productStock={}; BobbinWinderMaker.buildings={}; BobbinWinderMaker.maker=nil; BobbinWinderMaker.activeMaking={}; BobbinWinderMaker.totalProducts=0; BobbinWinderMaker.dayTimer=0; print("[BobbinWinderMaker] Royal Bobbin Winder Maker System initialized (6 products, 4 buildings)") end
function BobbinWinderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BobbinWinderMaker.maker={name=n or ("Navijalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalec najet: %s (spretnost: %d)",BobbinWinderMaker.maker.name,s),"success") end; return true end
function BobbinWinderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BobbinWinderMaker.build(id) local ok,e=BobbinWinderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BobbinWinderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BobbinWinderMaker.getQualityBonus() local b=0; for _,bd in ipairs(BobbinWinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BobbinWinderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BobbinWinderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BobbinWinderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BobbinWinderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BobbinWinderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BobbinWinderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BobbinWinderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BobbinWinderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BobbinWinderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BobbinWinderMaker.buildings==0 then return false,"Potrebna navijalna delavnica" end; if not BobbinWinderMaker.maker then return false,"Potreben navijalec" end; return true end
function BobbinWinderMaker.make(pt,qty) qty=qty or 1; local ok,e=BobbinWinderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BobbinWinderMaker.ironStock=BobbinWinderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BobbinWinderMaker.bronzeStock=BobbinWinderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BobbinWinderMaker.woodStock=BobbinWinderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BobbinWinderMaker.leatherStock=BobbinWinderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BobbinWinderMaker.silverStock=BobbinWinderMaker.silverStock-d.silverCost*qty end; if d.goldCost then BobbinWinderMaker.goldStock=BobbinWinderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BobbinWinderMaker.jewelStock=BobbinWinderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BobbinWinderMaker.pearlStock=BobbinWinderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BobbinWinderMaker.maker then t=math.max(1,t-math.floor(BobbinWinderMaker.maker.skill/13)) end; table.insert(BobbinWinderMaker.activeMaking,{id="bobbinwinder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BobbinWinderMaker.completeMaking(m) local q=1.0+(BobbinWinderMaker.getQualityBonus()/100); if BobbinWinderMaker.maker then q=q+(BobbinWinderMaker.maker.skill/140) end; q=math.min(2.5,q); BobbinWinderMaker.productStock[m.productType]=(BobbinWinderMaker.productStock[m.productType] or 0)+m.quantity; BobbinWinderMaker.totalProducts=BobbinWinderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BobbinWinderMaker.maker then BobbinWinderMaker.maker.itemsMade=BobbinWinderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BobbinWinderMaker.maker.skill=math.min(100,BobbinWinderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bobbinwinder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BobbinWinderMaker.update(dt) if not _G.state then return end; BobbinWinderMaker.dayTimer=BobbinWinderMaker.dayTimer+dt; if BobbinWinderMaker.dayTimer>=30 then BobbinWinderMaker.dayTimer=0; for i=#BobbinWinderMaker.activeMaking,1,-1 do local m=BobbinWinderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BobbinWinderMaker.completeMaking(m); table.remove(BobbinWinderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BobbinWinderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BobbinWinderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BobbinWinderMaker.getStats() return {ironStock=BobbinWinderMaker.ironStock,bronzeStock=BobbinWinderMaker.bronzeStock,woodStock=BobbinWinderMaker.woodStock,leatherStock=BobbinWinderMaker.leatherStock,silverStock=BobbinWinderMaker.silverStock,goldStock=BobbinWinderMaker.goldStock,jewelStock=BobbinWinderMaker.jewelStock,pearlStock=BobbinWinderMaker.pearlStock,productStock=BobbinWinderMaker.productStock,numBuildings=#BobbinWinderMaker.buildings,hasMaker=BobbinWinderMaker.maker~=nil,makerName=BobbinWinderMaker.maker and BobbinWinderMaker.maker.name or "—",makerSkill=BobbinWinderMaker.maker and BobbinWinderMaker.maker.skill or 0,activeMaking=#BobbinWinderMaker.activeMaking,totalProducts=BobbinWinderMaker.totalProducts} end
return BobbinWinderMaker
